void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85; // slightly more aggressive reduction to trigger rephase more often
    rephase_limit += 10240; // increase limit more to allow deeper exploration before restart
    // also update saved phases based on current trail to keep recent progress
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) saved[i] = value[i]; // save current assignment as preferred phase
        else if (rand() % 100 < 30) saved[i] = rand() % 2 ? 1 : -1; // randomize some unassigned
    }
}
